<script setup lang="ts">
import {computed,ref} from 'vue'
import PageShell from '../PageShell.vue'
import Icon from '../Icon.vue'
import DashboardSpark from '../DashboardSpark.vue'
import DashboardTraffic from '../DashboardTraffic.vue'
import {api,bytes,type AdminDashboard,type Probe} from '../api'
import {yuan} from '../commerce'
import {usePage} from '../page'
import type {DashboardPeriod} from '../dashboard-chart'
const data=ref<AdminDashboard|null>(null),period=ref<DashboardPeriod>('24h'),fetching=ref(false)
const samples=ref<{at:number;users:number;online:number;recharge:number;connections:number}[]>([])
const {me,loading,error,refresh}=usePage(async()=>{
 fetching.value=true
 try{
  const requested=period.value,result=await api<AdminDashboard>(`admin/dashboard?range=${requested}`)
  if(requested!==period.value)return
  data.value=result
  const at=Date.parse(result.generated_at),s=result.stats
  samples.value=[...samples.value.filter(p=>p.at!==at&&p.at<=at),{at,users:s.users,online:s.online_nodes,recharge:s.recharge_cents,connections:s.connections}].filter(p=>p.at>=at-300000).slice(-60)
 }finally{fetching.value=false}
},{admin:true,interval:10000})
const stats=computed(()=>data.value?.stats)
const pending=computed(()=>stats.value?.waiting_tickets||0)
const date=computed(()=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(data.value?.generated_at||Date.now())))
const time=computed(()=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(data.value?.generated_at||Date.now())))
const host=computed(()=>data.value?.host)
const rechargeURL=computed(()=>{const query=new URLSearchParams({kind:'recharge',status:'paid',time_field:'paid'});if(data.value){const now=Date.parse(data.value.generated_at),start=Math.floor((now+28800000)/86400000)*86400000-28800000;query.set('from',new Date(start).toISOString());query.set('to',data.value.generated_at)};return '/admin/orders?'+query.toString()})
const hostFresh=computed(()=>host.value&&Math.abs(Date.parse(data.value!.generated_at)/1000-(host.value.sampled_at||0))<20)
const orderNames:Record<string,string>={recharge:'余额充值',purchase:'套餐购买',renewal:'套餐续费',rebate:'邀请返利'}
const orderStates:Record<string,string>={paid:'已完成',pending:'待支付',cancelled:'已取消'}
function format(value:number){return value.toLocaleString('zh-CN')}
function money(value:number){return Number(yuan(value)).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}
function percent(p:Probe|null,kind:'cpu'|'memory'){
 if(!p)return '—'
 if(kind==='cpu')return p.cpu_ready?`${Number(p.cpu_percent||0).toFixed(1)}%`:'—'
 return p.memory_ready&&p.memory_total?`${(100*Number(p.memory_used||0)/p.memory_total).toFixed(1)}%`:'—'
}
function network(p:Probe|null,direction:'rx'|'tx'){return p?.network_ready?`${Number(p[`${direction}_mbps`]||0).toLocaleString('zh-CN',{maximumFractionDigits:1})} Mbps`:'—'}
function duration(seconds?:number){if(seconds==null)return '—';const d=Math.floor(seconds/86400),h=Math.floor(seconds%86400/3600),m=Math.floor(seconds%3600/60);return d?`${d} 天 ${h} 小时`:h?`${h} 小时 ${m} 分钟`:`${m} 分钟`}
function changePeriod(value:DashboardPeriod){if(period.value===value)return;period.value=value;void refresh()}
</script>
<template><PageShell :me="me" :loading="loading" :error="error" active="admin" admin :pending-tickets="stats?.waiting_tickets">
 <div v-if="data&&stats" class="admin-overview" data-testid="admin-overview">
  <div class="dashboard-heading"><div><h1>后台概览</h1><p>运行状态与业务数据</p></div><div class="dashboard-heading-actions"><time>{{date}}</time><el-button :loading="fetching" @click="refresh"><Icon name="refresh"/>刷新</el-button></div></div>
  <div class="dashboard-stats">
   <a class="surface dashboard-stat" href="/admin/users" data-testid="dashboard-users"><div class="dashboard-stat-label"><Icon name="user"/>用户总数</div><strong>{{format(stats.users)}}</strong><div class="dashboard-stat-detail"><span>今日新增 {{format(stats.new_users)}}</span><DashboardSpark :values="samples.map(s=>s.users)" label="最近五分钟用户数量"/></div></a>
   <a class="surface dashboard-stat" href="/admin/nodes" data-testid="dashboard-nodes"><div class="dashboard-stat-label"><Icon name="node"/>在线节点</div><strong>{{format(stats.online_nodes)}} <small>/ {{format(stats.enabled_nodes)}}</small></strong><div class="dashboard-stat-detail"><span :class="{'dashboard-warning':stats.offline_nodes}"><i :class="['status-dot',stats.offline_nodes?'warning':'healthy']"/>{{stats.offline_nodes?`${stats.offline_nodes} 个节点离线`:stats.enabled_nodes?'已启用节点全部在线':'暂无启用节点'}}</span><DashboardSpark :values="samples.map(s=>s.online)" color="var(--dashboard-mint)" label="最近五分钟在线节点数量"/></div></a>
   <a class="surface dashboard-stat" :href="rechargeURL" title="按 UTC+8 统计今日成功充值订单，不含套餐购买与邀请返利" data-testid="dashboard-recharge"><div class="dashboard-stat-label"><Icon name="wallet"/>今日充值</div><strong>¥{{money(stats.recharge_cents)}}</strong><div class="dashboard-stat-detail"><span>已完成 {{format(stats.recharge_orders)}} 笔</span><DashboardSpark :values="samples.map(s=>s.recharge)" label="最近五分钟今日充值金额"/></div></a>
   <a class="surface dashboard-stat" href="/admin/users" data-testid="dashboard-rules"><div class="dashboard-stat-label"><Icon name="switch"/>转发规则</div><strong>{{format(stats.rules)}}</strong><div class="dashboard-stat-detail"><span title="在线节点上报的活动转发连接合计">当前连接 {{format(stats.connections)}}</span><DashboardSpark :values="samples.map(s=>s.connections)" color="var(--dashboard-mint)" label="最近五分钟节点活动连接合计"/></div></a>
  </div>
  <div class="dashboard-middle">
   <section class="surface dashboard-traffic"><div class="dashboard-card-heading"><h2>全网流量</h2><div class="dashboard-period" role="group" aria-label="流量时间范围"><button v-for="item in ([['24h','24 小时'],['7d','7 天'],['30d','30 天']] as const)" :key="item[0]" :class="{active:period===item[0]}" :aria-pressed="period===item[0]" @click="changePeriod(item[0])">{{item[1]}}</button></div></div><div class="dashboard-traffic-summary" title="节点探针网卡流量合计，包含隧道开销；非套餐计费流量"><span>今日流量 <strong>{{stats.traffic_ready?bytes(stats.today_rx+stats.today_tx):'等待采样'}}</strong></span><small>上传 {{stats.traffic_ready?bytes(stats.today_tx):'—'}}</small><small>下载 {{stats.traffic_ready?bytes(stats.today_rx):'—'}}</small></div><DashboardTraffic :points="data.range===period?data.traffic:[]" :period="period" :unit="period==='24h'?'mbps':'bytes'" :at="Date.parse(data.generated_at)/1000"/></section>
   <section class="surface dashboard-tasks" data-testid="dashboard-tickets"><div class="dashboard-card-heading"><h2>待处理工单</h2><span class="dashboard-count" :class="{quiet:!pending}">{{pending}}</span></div>
    <div v-if="pending" class="dashboard-task-list"><a v-for="item in ([['high','高优先级',stats.high_tickets,'danger'],['medium','中优先级',stats.medium_tickets,'warning'],['low','低优先级',stats.low_tickets,'info']] as const)" :key="item[0]" :href="`/admin/tickets?status=waiting_staff&priority=${item[0]}`"><Icon name="rules"/><span>{{item[1]}}<small>等待客服回复</small></span><b :class="item[2]?item[3]:''">{{item[2]}}</b><span class="dashboard-chevron">›</span></a></div>
    <div v-else class="dashboard-tickets-empty"><Icon name="check"/><p>暂无待处理工单</p></div>
    <div class="dashboard-ticket-footer"><a href="/admin/tickets">查看全部工单 <span>→</span></a></div>
   </section>
  </div>
  <div class="dashboard-bottom">
   <section class="surface dashboard-node-panel"><div class="dashboard-card-heading"><h2>节点概况</h2><a href="/admin/nodes">查看全部 →</a></div><div class="dashboard-table-scroll"><table class="dashboard-table"><thead><tr><th>节点</th><th>状态</th><th>CPU</th><th>内存</th><th>实时速率</th></tr></thead><tbody><tr v-for="n in data.nodes" :key="n.id"><td><a href="/admin/nodes" :title="n.name" class="dashboard-node-name">{{n.name}}</a></td><td><span :class="['dashboard-node-state',!n.enabled?'muted':n.online?'healthy':'danger']"><i class="status-dot" :class="!n.enabled?'muted':n.online?'healthy':'danger'"/>{{!n.enabled?'停用':n.online?'在线':'离线'}}</span></td><td><div class="dashboard-resource"><span>{{percent(n.metrics,'cpu')}}</span><DashboardSpark v-if="n.online&&n.metrics?.cpu_ready" :values="n.history.map(p=>p.cpu)" percentage label="CPU 最近采样趋势"/></div></td><td><div class="dashboard-resource"><span>{{percent(n.metrics,'memory')}}</span><DashboardSpark v-if="n.online&&n.metrics?.memory_ready" :values="n.history.map(p=>p.memory)" percentage color="var(--dashboard-mint)" label="内存最近采样趋势"/></div></td><td><div class="dashboard-network"><span>↑ {{network(n.metrics,'tx')}}</span><span>↓ {{network(n.metrics,'rx')}}</span></div></td></tr><tr v-if="!data.nodes.length"><td colspan="5" class="dashboard-empty">暂无节点，<a href="/admin/nodes?create=1">添加第一个节点</a></td></tr></tbody></table></div></section>
   <section class="surface dashboard-order-panel"><div class="dashboard-card-heading"><h2>最近订单</h2><a href="/admin/orders">全部订单 →</a></div><div class="dashboard-table-scroll"><table class="dashboard-table"><thead><tr><th>用户</th><th>类型</th><th>金额</th><th>状态</th></tr></thead><tbody><tr v-for="o in data.orders" :key="o.id"><td><a class="dashboard-order-user" :title="o.username" :href="`/admin/orders?order_no=${encodeURIComponent(o.order_no)}`">{{o.username}}</a></td><td>{{orderNames[o.kind]||o.kind}}</td><td class="dashboard-money" :class="{'dashboard-positive':o.kind==='rebate'}">{{o.kind==='rebate'?'+':''}}¥{{money(o.amount_cents)}}</td><td><span :class="['dashboard-order-status',o.status]">{{orderStates[o.status]||o.status}}</span></td></tr><tr v-if="!data.orders.length"><td colspan="4" class="dashboard-empty">暂无订单</td></tr></tbody></table></div></section>
  </div>
  <footer class="surface dashboard-host"><span class="dashboard-host-label"><Icon name="node"/>面板主机</span><span :class="['dashboard-host-state',hostFresh?'healthy':'muted']"><i class="status-dot" :class="hostFresh?'healthy':'muted'"/>{{hostFresh?'运行正常':'采样中'}}</span><template v-if="hostFresh&&host"><span>CPU {{percent(host,'cpu')}}</span><span>内存 {{host.memory_ready?`${bytes(host.memory_used||0)} / ${bytes(host.memory_total||0)}`:'—'}}</span><span>磁盘 {{host.disk_ready?`${bytes(host.disk_used||0)} / ${bytes(host.disk_total||0)}`:'—'}}</span><span>运行 {{host.uptime_ready?duration(host.uptime_seconds):'—'}}</span></template><small>更新于 {{time}} · UTC+8</small></footer>
 </div>
 <section v-else class="surface dashboard-unavailable"><h2>后台概览暂不可用</h2><p class="subtle">请稍后重试</p><el-button :loading="fetching" @click="refresh">重新加载</el-button></section>
</PageShell></template>
<style scoped>
.dashboard-unavailable{padding:36px;text-align:center}.admin-overview{--dashboard-blue:#3988ed;--dashboard-mint:#329d85;padding:4px 10px 16px;display:grid;gap:20px;min-width:0}.dark .admin-overview{--dashboard-blue:#73afff;--dashboard-mint:#75c9b2}
.admin-overview .surface{border-radius:10px;box-shadow:none}.dashboard-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;padding-bottom:2px}.dashboard-heading h1{font-size:25px;line-height:1.3;letter-spacing:.02em;margin:0 0 6px;font-weight:650}.dashboard-heading p{margin:0;color:var(--muted);font-size:13px}.dashboard-heading-actions{display:flex;align-items:center;gap:20px}.dashboard-heading-actions time{font-variant-numeric:tabular-nums;font-size:13px}
.dashboard-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px}.dashboard-stat{display:block;padding:17px 19px 13px;min-width:0;transition:border-color .15s}.dashboard-stat:hover{border-color:var(--el-color-primary)}.dashboard-stat-label{display:flex;align-items:center;gap:10px;font-size:13px;font-weight:550;margin-bottom:10px}.dashboard-stat-label .ui-icon{width:18px;height:18px}.dashboard-stat>strong{display:block;font-size:29px;line-height:1.2;font-weight:650;font-variant-numeric:tabular-nums;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.dashboard-stat>strong small{font-size:23px;font-weight:500}.dashboard-stat-detail{display:flex;align-items:center;justify-content:space-between;gap:5px;color:var(--muted);font-size:12px;margin-top:5px;min-height:28px}.dashboard-stat-detail>span{display:inline-flex;align-items:center;gap:7px;min-width:0}.dashboard-stat-detail :deep(.dashboard-spark){width:72px;height:28px;flex-shrink:1}
.status-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:currentColor;flex-shrink:0}.healthy{color:var(--dashboard-mint)}.warning,.dashboard-warning{color:var(--el-color-warning,#c88721)}.danger{color:var(--el-color-danger,#d94848)}.muted{color:var(--muted)}
.dashboard-middle{display:grid;grid-template-columns:minmax(0,2.1fr) minmax(300px,1fr);gap:20px}.dashboard-traffic,.dashboard-tasks{padding:18px 20px;min-width:0}.dashboard-card-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:25px;margin-bottom:12px}.dashboard-card-heading h2{font-size:17px;font-weight:650;line-height:1.4;margin:0}.dashboard-card-heading>a{font-size:12px;color:var(--el-color-primary);white-space:nowrap}.dashboard-period{display:flex;border:1px solid var(--el-border-color);border-radius:6px;overflow:hidden;flex-shrink:0}.dashboard-period button{border:0;background:transparent;color:var(--muted);padding:6px 11px;font-size:12px}.dashboard-period button+button{border-left:1px solid var(--border)}.dashboard-period button.active{background:var(--el-color-primary);color:#fff}.dashboard-traffic-summary{display:flex;align-items:baseline;gap:17px;flex-wrap:wrap;margin:2px 0 10px;font-size:12px}.dashboard-traffic-summary strong{font-size:20px;font-weight:650;margin-left:7px;white-space:nowrap}.dashboard-traffic-summary small{font-size:12px;color:var(--muted)}
.dashboard-tasks{display:flex;flex-direction:column}.dashboard-count{background:var(--el-color-danger,#d94848);color:#fff;border-radius:20px;font-size:11px;min-width:21px;padding:2px 6px;text-align:center;margin-right:auto}.dashboard-count.quiet{background:var(--el-fill-color-light);color:var(--muted)}.dashboard-task-list>a{display:flex;align-items:center;gap:12px;width:100%;padding:13px 4px;color:inherit;border:0;border-bottom:1px solid var(--border);background:transparent;text-align:left;font-size:13px}.dashboard-task-list>a:hover{color:var(--el-color-primary)}.dashboard-task-list>a>span:nth-child(2){flex:1}.dashboard-task-list b{font-size:11px;font-weight:500;border-radius:20px;min-width:22px;padding:3px 6px;text-align:center;background:var(--el-fill-color-light);color:var(--muted)}.dashboard-task-list b.danger{background:var(--el-color-danger);color:#fff}.dashboard-task-list b.warning{background:var(--el-color-warning);color:#fff}.dashboard-task-list small{display:block;color:var(--muted);font-size:10px;margin-top:3px}.dashboard-chevron{font-size:19px;color:var(--muted)}
.dashboard-task-list b.info{background:var(--el-color-primary);color:#fff}.dashboard-tickets-empty{display:grid;place-content:center;justify-items:center;min-height:160px;flex:1;color:var(--muted);font-size:13px}.dashboard-tickets-empty .ui-icon{width:30px;height:30px;color:var(--dashboard-mint)}.dashboard-ticket-footer{margin-top:auto;padding-top:20px}.dashboard-ticket-footer a{display:flex;justify-content:space-between;align-items:center;padding:10px 12px;border:1px solid var(--el-border-color);border-radius:5px;font-size:12px;color:var(--el-color-primary)}
.dashboard-bottom{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(0,1fr);gap:20px}.dashboard-node-panel,.dashboard-order-panel{padding:17px 17px 14px;min-width:0}.dashboard-table-scroll{overflow-x:auto}.dashboard-table{width:100%;border-collapse:collapse;font-size:12px;white-space:nowrap;text-align:left;font-variant-numeric:tabular-nums}.dashboard-table th{background:var(--el-fill-color-light);font-size:12px;font-weight:550;padding:9px 10px}.dashboard-table td{height:38px;padding:7px 10px;border-bottom:1px solid var(--border)}.dashboard-table tbody tr:last-child td{border-bottom:0}.dashboard-table tr:hover td{background:var(--el-color-primary-light-9)}.dashboard-node-name,.dashboard-order-user{display:block;max-width:125px;overflow:hidden;text-overflow:ellipsis}.dashboard-order-user{max-width:135px}.dashboard-node-state{display:inline-flex;align-items:center;gap:6px;font-size:11px}.dashboard-resource{display:flex;align-items:center;gap:8px}.dashboard-resource>span{min-width:43px}.dashboard-resource :deep(.dashboard-spark){width:55px;height:22px}.dashboard-network{display:flex;align-items:center;gap:9px;font-size:11px}.dashboard-positive{color:var(--dashboard-mint)}.dashboard-order-status{display:inline-block;padding:3px 7px;border-radius:20px;font-size:10px;line-height:1.3;background:var(--el-fill-color-light);color:var(--muted)}.dashboard-order-status.paid{color:var(--el-color-success);background:var(--el-color-success-light-9)}.dashboard-order-status.pending{color:var(--el-color-warning);background:var(--el-color-warning-light-9)}.dashboard-empty{height:130px!important;text-align:center;color:var(--muted)}.dashboard-empty a{color:var(--el-color-primary)}
.dashboard-host{display:flex;align-items:center;gap:20px;padding:12px 17px;font-size:11px;flex-wrap:wrap;font-variant-numeric:tabular-nums}.dashboard-host-label{display:inline-flex;align-items:center;gap:8px;font-weight:550;font-size:12px}.dashboard-host-state{display:flex;align-items:center;gap:6px;background:var(--el-fill-color-light);padding:5px 8px;border-radius:5px}.dashboard-host small{color:var(--muted);font-size:10px;margin-left:auto}@media(min-width:1700px){.admin-overview{padding:5px 18px 20px;gap:22px}.dashboard-stat{padding:19px 22px 15px}.dashboard-traffic,.dashboard-tasks{padding:20px 24px}.dashboard-node-panel,.dashboard-order-panel{padding:20px 20px 16px}.dashboard-table td{height:41px}}
@media(max-width:1450px){.dashboard-resource :deep(.dashboard-spark){display:none}.dashboard-order-user{max-width:100px}}
@media(max-width:1250px){.dashboard-stats{gap:14px}.dashboard-stat{padding:15px 15px 10px}.dashboard-stat>strong{font-size:25px}.dashboard-stat-detail :deep(.dashboard-spark){width:48px}.dashboard-middle{grid-template-columns:minmax(0,1.9fr) minmax(270px,1fr);gap:16px}.dashboard-bottom{grid-template-columns:1fr;gap:16px}.dashboard-traffic,.dashboard-tasks{padding:17px}.dashboard-host{gap:12px}.dashboard-network{gap:15px}.dashboard-resource :deep(.dashboard-spark){width:80px}}
@media(max-width:900px){.dashboard-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.dashboard-middle{grid-template-columns:1fr}.dashboard-tasks{min-height:245px}.dashboard-stat>strong{font-size:28px}.dashboard-stat-detail :deep(.dashboard-spark){width:75px}.dashboard-heading-actions{gap:10px}}
@media(max-width:600px){.admin-overview{padding:4px 0 12px;gap:15px}.dashboard-heading{gap:10px}.dashboard-heading h1{font-size:21px}.dashboard-heading-actions time{display:none}.dashboard-heading-actions .el-button{padding:6px 10px}.dashboard-stats{gap:10px}.dashboard-stat{padding:13px 12px 9px}.dashboard-stat-label{font-size:12px;gap:7px}.dashboard-stat>strong{font-size:24px}.dashboard-stat>strong small{font-size:19px}.dashboard-stat-detail{font-size:10px}.dashboard-stat-detail :deep(.dashboard-spark){width:40px}.dashboard-traffic,.dashboard-tasks{padding:14px 12px}.dashboard-card-heading h2{font-size:16px}.dashboard-period button{font-size:11px;padding:5px 8px}.dashboard-traffic-summary{gap:8px 12px;margin-bottom:12px}.dashboard-traffic-summary strong{font-size:18px}.dashboard-node-panel,.dashboard-order-panel{padding:14px 12px 10px}.dashboard-resource :deep(.dashboard-spark){width:42px}.dashboard-table{font-size:11px}.dashboard-table th,.dashboard-table td{padding:9px 8px}.dashboard-host{padding:12px;font-size:10px;gap:10px 14px}.dashboard-host small{margin-left:0;width:100%;padding-top:4px}}
</style>
